151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        normalizeEmail(ownerFieldsDto);
158	        currentOwner.setAddress(ownerFieldsDto.getAddress());
159	        currentOwner.setCity(ownerFieldsDto.getCity());
160	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
161	        currentOwner.setLastName(ownerFieldsDto.getLastName());
162	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
163	        currentOwner.setEmail(ownerFieldsDto.getEmail());
164	        this.clinicService.saveOwner(currentOwner);
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
166	    }
