182	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Pet pet = petMapper.toPet(petFieldsDto);
189	        owner.setId(ownerId);
190	        pet.setOwner(owner);
191	        pet.getType().setName(null);
192	        this.clinicService.savePet(pet);
193	        PetDto petDto = petMapper.toPetDto(pet);
194	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
195	            .buildAndExpand(pet.getId()).toUri());
196	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
197	    }
