292	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
293	        List<String> errors = new ArrayList<>();
294	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
295	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
296	        requireText("address", ownerFieldsDto.getAddress(), errors);
297	        requireText("city", ownerFieldsDto.getCity(), errors);
298	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
299	        if (!errors.isEmpty()) {
300	            throw new RequiredFieldsMissingException(errors);
301	        }
302	    }
303	
304	    private static void requireText(String field, String value, List<String> errors) {
305	        if (value == null || value.isBlank()) {
306	            errors.add(field);
307	        }
308	    }
309	
310	    /**
311	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
312	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
313	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
314	     */
315	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
316	        "NSW", new int[] {2000, 2099},
317	        "VIC", new int[] {3000, 3099},
318	        "QLD", new int[] {4000, 4099});
319	
320	    /**
321	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
322	     * {@code null} value is accepted. When present it has already been constrained to four digits
323	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
324	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
325	     * the postcode must fall within that region's inclusive range
326	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
327	     *
328	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
329	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
330	     *                                  city's region
331	     */
332	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
333	        String postcode = ownerFieldsDto.getPostcode();
334	        if (postcode == null) {
335	            return;
336	        }
337	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
338	            .regionFor(ownerFieldsDto.getCity());
339	        int[] range = REGION_POSTCODE_RANGE.get(region);
340	        if (range == null) {
341	            return;
342	        }
343	        int value = Integer.parseInt(postcode);
344	        if (value < range[0] || value > range[1]) {
345	            throw new InvalidPostcodeException(postcode);
346	        }
347	    }
348	
349	    /**
350	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
351	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
352	     * and echoed back in that form.
353	     *
354	     * @param ownerFieldsDto the submitted owner fields
355	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
356	     *                                        valid E.164 number
357	     */
358	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
359	        String e164 = toE164(ownerFieldsDto.getTelephone());
360	        if (e164 == null) {
361	            throw new RequiredFieldsMissingException(List.of("telephone"));
362	        }
363	        ownerFieldsDto.setTelephone(e164);
364	    }
365	
366	    /**
367	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
368	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
369	     * and country code are present they are kept; otherwise country code {@code '+61'} is
370	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
371	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
372	     * the national-number length must match the country: {@code '+61'} (Australia) requires
373	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
374	     *
375	     * @param raw the submitted telephone, possibly {@code null}
376	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
377	     */
378	    private static String toE164(String raw) {
379	        if (raw == null) {
380	            return null;
381	        }
382	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
383	        String digits;
384	        if (cleaned.startsWith("+")) {
385	            digits = cleaned.substring(1);
386	        } else {
387	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
388	            digits = "61" + national;
389	        }
390	        if (!digits.matches("[0-9]{8,15}")) {
391	            return null;
392	        }
393	        if (digits.startsWith("61")) {
394	            // Australia: exactly 9 national digits after the '+61' country code.
395	            if (digits.length() - 2 != 9) {
396	                return null;
397	            }
398	        } else if (digits.startsWith("1")) {
399	            // NANP: exactly 10 national digits after the '+1' country code.
400	            if (digits.length() - 1 != 10) {
401	                return null;
402	            }
403	        }
404	        return "+" + digits;
405	    }
