407	    /**
408	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
409	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
410	     * each stored owner's telephone is normalized the same way before comparison so differing
411	     * input formats collapse to the same value.
412	     *
413	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
414	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
415	     *                                     same E.164 telephone
416	     */
417	    /**
418	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
419	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
420	     * the parts may contain whitespace or a second {@code @}.
421	     */
422	    private static final Pattern EMAIL_PATTERN =
423	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
424	
425	    /**
426	     * Normalizes the submitted email when present: the value is trimmed, required to be a
427	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
428	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
429	     *
430	     * @param ownerFieldsDto the submitted owner fields
431	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
432	     */
433	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
434	        String email = ownerFieldsDto.getEmail();
435	        if (email == null) {
436	            return;
437	        }
438	        String trimmed = email.strip();
439	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
440	            throw new InvalidEmailException(email);
441	        }
442	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
443	    }
444	
445	    /**
446	     * Establishes the effective registration date on create and rolls it onto a business day.
447	     * When the client does not supply a {@code registrationDate} it defaults to the server's
448	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
449	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
450	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
451	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
452	     * the membership number's year segment and the daily create-limit).
453	     *
454	     * @param ownerFieldsDto the submitted owner fields
455	     */
456	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
457	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
458	        if (effective == null) {
459	            effective = LocalDate.now();
460	        }
461	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
462	    }
463	
464	    /**
465	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
466	     * following Monday; any weekday is returned unchanged.
467	     *
468	     * @param date the date to adjust
469	     * @return the same date when it is a weekday, otherwise the next Monday
470	     */
471	    private static LocalDate toBusinessDay(LocalDate date) {
472	        return switch (date.getDayOfWeek()) {
473	            case SATURDAY -> date.plusDays(2);
474	            case SUNDAY -> date.plusDays(1);
475	            default -> date;
476	        };
477	    }
478	
479	    /**
480	     * Assigns the owner's {@code customerCode} on create, formatted
481	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
482	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
483	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
484	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
485	     *
486	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
487	     */
488	    private void assignCustomerCode(Owner owner) {
489	        String city = owner.getCity();
490	        String lastName = owner.getLastName();
491	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
492	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
493	        long sequence = this.clinicService.findAllOwners().stream()
494	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
495	            .count() + 1;
496	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
497	    }
498	
499	    /**
500	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
501	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
502	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
503	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
504	     * canonicalized fields, every owner in the same household — including one joining an existing
505	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
506	     * order.
507	     *
508	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
509	     */
510	    private void assignHouseholdId(Owner owner) {
511	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
512	    }
513	
514	    /**
515	     * Derives the stable {@code householdId} for the given {@code lastName} and {@code address}:
516	     * {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the SHA-256
517	     * digest of the collapsed {@code lastName} and {@code address} (see {@link #collapse}) joined
518	     * by a {@code '\n'}. Because it is derived purely from those two canonicalized fields, every
519	     * owner in the same household receives the same value, independent of create order. Shared by
520	     * {@link #assignHouseholdId} (which persists it) and {@link #identityKeyFor} (which folds it
521	     * into the identity key for duplicate detection).
522	     *
523	     * @param lastName the owner's last name
524	     * @param address  the owner's address
525	     * @return the derived household id
526	     */
527	    private static String householdIdFor(String lastName, String address) {
528	        String key = collapse(lastName) + "\n" + collapse(address);
529	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
530	    }
531	
532	    /**
533	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
534	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
535	     * after this create. Because {@code householdId} is derived from the owner's collapsed
536	     * {@code lastName} and {@code address} (see {@link #assignHouseholdId}), the count reflects every
537	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
538	     * The count is taken before this owner is persisted, so it is one more than the number of
539	     * existing household members.
540	     *
541	     * @param owner the owner being created (with its {@code householdId} already assigned)
542	     */
543	    private void assignHouseholdMemberCount(Owner owner) {
544	        String householdId = owner.getHouseholdId();
545	        long existing = this.clinicService.findAllOwners().stream()
546	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
547	            .count();
548	        owner.setHouseholdMemberCount((int) (existing + 1));
549	    }
550	
551	    /**
552	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
553	     * already share this owner's {@code firstName} and {@code lastName}, compared
554	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
555	     * pre-existing namesakes.
556	     *
557	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
558	     */
559	    private void assignNamesakeCount(Owner owner) {
560	        String firstName = owner.getFirstName();
561	        String lastName = owner.getLastName();
562	        long count = this.clinicService.findAllOwners().stream()
563	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
564	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
565	            .count();
566	        owner.setNamesakeCount((int) count);
567	    }
568	
569	    /**
570	     * Assigns the owner's {@code membershipNumber} on create, formatted
571	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
572	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
573	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
574	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
575	     *
576	     * @param owner the owner being created (with its {@code customerCode} and
577	     *              {@code registrationDate} already set)
578	     */
579	    private void assignMembershipNumber(Owner owner) {
580	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
581	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
582	    }
583	
584	    /**
585	     * The number of owners that must already carry a registration date before a subsequent
586	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
587	     * once the count of owners already registered on that day <em>exceeds</em> this value.
588	     */
589	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
590	
591	    /**
592	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
593	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
594	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
595	     * existing owners before this one is persisted, so it reflects only the owners already
596	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
597	     *
598	     * @param owner the owner being created (with its {@code registrationDate} already set)
599	     */
600	    private void assignBulkSignupWarning(Owner owner) {
601	        LocalDate registrationDate = owner.getRegistrationDate();
602	        long count = this.clinicService.findAllOwners().stream()
603	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
604	            .count();
605	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
606	    }
607	
608	    /**
609	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
610	     *
611	     * @param value the string to hash
612	     * @return the 64-character lower-case hex digest
613	     */
614	    private static String sha256Hex(String value) {
615	        try {
616	            byte[] digest = MessageDigest.getInstance("SHA-256")
617	                .digest(value.getBytes(StandardCharsets.UTF_8));
618	            StringBuilder sb = new StringBuilder(digest.length * 2);
619	            for (byte b : digest) {
620	                sb.append(String.format("%02x", b));
621	            }
622	            return sb.toString();
623	        }
624	        catch (NoSuchAlgorithmException e) {
625	            throw new IllegalStateException("SHA-256 not available", e);
626	        }
627	    }
628	
629	    /**
630	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
631	     * owner. This single key consolidates what used to be three separate duplicate checks
632	     * (telephone, email and household): the key is
633	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
634	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
635	     * matches an existing owner's. Because the telephone is part of the key, two members of the
636	     * same household (same {@code householdId}) with different telephones have different identity
637	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
638	     * and email have already been normalized by {@link #normalizeTelephone} and
639	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
640	     * input formats collapse to the same value.
641	     *
642	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
643	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
644	     *                                    whole identity key
645	     */
646	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
647	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress(),
648	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
649	        boolean duplicate = this.clinicService.findAllOwners().stream()
650	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getAddress(),
651	                owner.getTelephone(), owner.getEmail()))
652	            .anyMatch(identityKey::equals);
653	        if (duplicate) {
654	            throw new DuplicateIdentityException(identityKey);
655	        }
656	    }
657	
658	    /**
659	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
660	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
661	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
662	     * absent), and the {@code householdId} is derived from the collapsed {@code lastName} and
663	     * {@code address} the same way {@link #assignHouseholdId} assigns it (see
664	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
665	     * their whole identities match, regardless of the exact input formats.
666	     *
667	     * @param lastName  the owner's last name
668	     * @param address   the owner's address
669	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
670	     * @param email     the owner's email, possibly {@code null}
671	     * @return the canonical identity key
672	     */
673	    private static String identityKeyFor(String lastName, String address, String telephone, String email) {
674	        String normalizedTelephone = toE164(telephone);
675	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
676	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
677	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, address);
678	    }
679	
680	    /**
681	     * The maximum number of owners permitted in a single city. A create is rejected once the
682	     * owner's city already contains this many owners.
683	     */
684	    private static final long CITY_CAPACITY = 50;
685	
686	    /**
687	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
688	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
689	     * before this owner is persisted.
690	     *
691	     * @param city the submitted city
692	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
693	     */
694	    private void rejectCityAtCapacity(String city) {
695	        long count = this.clinicService.findAllOwners().stream()
696	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
697	            .count();
698	        if (count >= CITY_CAPACITY) {
699	            throw new CityAtCapacityException(city);
700	        }
701	    }
702	
703	    /**
704	     * The maximum number of owners permitted to be created in a single day. A create is
705	     * rejected once this many owners already carry today's {@code registrationDate}.
706	     */
707	    private static final long DAILY_LIMIT = 100;
708	
709	    /**
710	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
711	     * business day as their {@code registrationDate}. The day counted against is this create's
712	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
713	     * so owners are counted per adjusted business day. The count is taken before this owner is
714	     * persisted.
715	     *
716	     * @param businessDay the effective, business-day-adjusted registration date of this create
717	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
718	     */
719	    private void rejectDailyLimit(LocalDate businessDay) {
720	        long count = this.clinicService.findAllOwners().stream()
721	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
722	            .count();
723	        if (count >= DAILY_LIMIT) {
724	            throw new DailyOwnerLimitExceededException(businessDay);
725	        }
726	    }
727	
728	    /**
729	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
730	     * every internal run of whitespace is collapsed to a single space, and the result is
731	     * lower-cased. A {@code null} value collapses to the empty string.
732	     *
733	     * @param value the value to canonicalize, possibly {@code null}
734	     * @return the collapsed, lower-cased value
735	     */
736	    private static String collapse(String value) {
737	        if (value == null) {
738	            return "";
739	        }
740	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
741	    }
742	
743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Override
745	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
746	        Owner owner = this.clinicService.findOwnerById(ownerId);
747	        if (owner != null) {
748	            Pet pet = owner.getPet(petId);
749	            if (pet != null) {
750	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
751	            }
752	        }
753	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
754	    }
755	}
